import{_ as r,l,o as e,c as s,v as o,p as n,x as t,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"批次分派与重工","description":"","frontmatter":{"title":"批次分派与重工","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lot-disposition-rework.md","filePath":"litho/lot-disposition-rework.md","lastUpdated":1789023840000}'),h={name:"litho/lot-disposition-rework.md"};function A(c,a,_,m,B,u){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="批次分派与重工" tabindex="-1">批次分派与重工 <a class="header-anchor" href="#批次分派与重工" aria-label="Permalink to &quot;批次分派与重工&quot;">​</a></h1><div class="epigraph"><p>超规格的批要决定：放行、重工、降级还是报废。分派是良率与周期的交叉口，不是控制图上的一个红点。</p><footer>—— 对照晶圆厂 lot disposition 与光刻重工（剥胶再曝）的产线通称</footer></div><p><a href="/litho/high-order-field-correction">上一课</a>把能补的高阶用尽。缺口是决策：残差仍超、或 SPC 异常、或检测出缺陷，批次去哪。本课钉分派与重工。计量机台之间如何可比，留给[下一课](/litho/metrology-matching）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>光刻重工通常是：显影后（或未刻蚀）剥胶、再涂、再曝。套刻或 CD 在 ADI 超规格时，重工可能划算；AEI 后重工变成刻蚀后，成本跳到报废或额外掩模。分派还含：扣留待加密计量、在替代机台重曝、降级到宽松产品。错误放行把风险送到测试；过度重工伤胶与衬底、吃产能、引入二次缺陷。</p><p>缺口是<strong>决策树</strong>，不是再讲 SPC。APC 限幅后的批默认扣留，而不是自动重工——可能是刻蚀问题。PWQ 场绝对不能当量产放行。</p><h3 id="重工改变历史" tabindex="-1">重工改变历史 <a class="header-anchor" href="#重工改变历史" aria-label="Permalink to &quot;重工改变历史&quot;">​</a></h3><p>重工片的热、应力、对准标记经历不同，套刻指纹可能变。R2R 应标记重工片，避免用它们更新机台指纹。胶剥离对 EUV 底层和疏水表面有损伤风险，次数要有上限。</p><p><span class="marginnote">边缘球与再涂均匀性往往比第一次差。重工后抽样应加密，而不是沿用标准计划。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>树：计量类型（CD/套刻/缺陷）× 轮廓（ADI/AEI）× 是否可剥 × 规格距离 × WIP 优先级。输出：放行、重工、报废、降级、工程分析。与轨道：剥胶路径、再涂食谱。与扫描机：是否换机重曝（匹配课）。记录：分派代码进追溯，供良率学习。</p><p>工程分析路径要有时限：扣留不是无限停车场。代码应能 join 到缺陷类和 APC 限幅事件，否则学习曲线看不到「因何重工」。SEMI 工厂系统对 lot 状态的接口，就是为了让这棵树可审计。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>期望损失 = P(测试失败)×成本 + 重工成本 + 周期惩罚。悬崖边的批，加密抽样降低误放行。系统缺陷（错版、错色）重工有效；随机缺陷重工可能只换一组光子，期望收益小——随机良率课再定量。</p>',14)),(e(),n(E,null,{default:t(()=>[p(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22ADI%20%E8%B6%85%E8%A7%84%E6%A0%BC%20%2F%20SPC%22%5D%20--%3E%20TREE%5B%22%E5%88%86%E6%B4%BE%E6%A0%91%22%5D%0A%20%20TREE%20--%3E%20RW%5B%22%E5%89%A5%E8%83%B6%E9%87%8D%E5%B7%A5%22%5D%0A%20%20TREE%20--%3E%20SCR%5B%22%E6%8A%A5%E5%BA%9F%22%5D%0A%20%20TREE%20--%3E%20REL%5B%22%E6%94%BE%E8%A1%8C%20%2F%20%E9%99%8D%E7%BA%A7%22%5D%0A%20%20RW%20--%3E%20TAG%5B%22%E6%A0%87%E8%AE%B0%E5%8B%BF%E8%BF%9B%E6%8C%87%E7%BA%B9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>重工片必须打标，以免 APC 把再涂指纹当成机台稳态。随机缺陷重工只是换一组抽签，期望收益有限。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写测试程序。不规定某厂的重工次数上限数字。AEI 后「重工」往往不是光刻重工。</p><p>后课默认：ADI 超规格才谈剥胶；重工片不更新稳态指纹。下一课保证做分派用的计量在机台间可比。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分派是放行/重工/报废树，按 ADI/AEI 与缺陷类型分支。</li><li>重工片要标记，以免污染 APC 指纹。</li><li>随机缺陷重工收益有限。</li><li>出处：晶圆厂 disposition 与 litho rework 通称；SEMI 工厂系统对 lot 状态的接口。</li></ul>',6))])}const D=r(h,[["render",A]]);export{f as __pageData,D as default};
